(function () { 'use strict'; function push(eventName, params) { params = params || {}; window.dataLayer = window.dataLayer || []; window.dataLayer.push(Object.assign({ event: eventName }, params)); if (typeof window.gtag === 'function') { window.gtag('event', eventName, params); } } function cartItems() { try { var raw = JSON.parse(localStorage.getItem('shopvivaliz_cart') || '[]'); return Array.isArray(raw) ? raw.map(function (item) { return { item_id: String(item.sku || item.id || item.olist_product_id || ''), item_name: String(item.name || 'Produto Vivaliz'), price: Number(item.price || 0), quantity: Math.max(1, Number(item.quantity || 1)) }; }) : []; } catch (error) { return []; } } function total(items) { return items.reduce(function (sum, item) { return sum + Number(item.price || 0) * Number(item.quantity || 1); }, 0); } function addBoletoOption() { var options = document.querySelector('.payment-options'); if (!options || options.querySelector('input[value="boleto"]')) return; var label = document.createElement('label'); label.className = 'payment-opt'; label.setAttribute('data-payment-enhancement', 'boleto'); label.innerHTML = '' + '<input type="radio" name="payment_method" value="boleto" required>' + '<span class="payment-opt-box">' + '<strong>Boleto bancário</strong>' + '<small>Emissão imediata pelo Mercado Pago. Pedido confirmado após compensação.</small>' + '</span>'; var infinitePay = options.querySelector('input[value="infinitepay"]'); var infiniteLabel = infinitePay ? infinitePay.closest('label') : null; options.insertBefore(label, infiniteLabel || null); var note = document.querySelector('.payment-options-note'); if (note) { note.textContent = 'Escolha boleto para emissão direta ou um dos gateways para Pix/cartão; as condições finais aparecem antes do pagamento.'; } } function bindPaymentAnalytics() { var form = document.getElementById('checkout-form'); if (!form || form.dataset.paymentAnalyticsBound === '1') return; form.dataset.paymentAnalyticsBound = '1'; form.addEventListener('submit', function () { var selected = form.querySelector('input[name="payment_method"]:checked'); var items = cartItems(); push('add_payment_info', { currency: 'BRL', value: total(items), payment_type: selected ? selected.value : 'unknown', items: items }); }, true); } function preventPrematurePurchaseEvents() { window.triggerGooglePurchaseEvent = function (orderNumber, value, items) { push('order_created', { transaction_id: String(orderNumber || ''), currency: 'BRL', value: Number(value || 0), payment_status: 'pending', items: Array.isArray(items) ? items : [] }); }; window.triggerGoogleAdsConversion = function (orderNumber, value) { push('ads_conversion_pending_payment', { transaction_id: String(orderNumber || ''), currency: 'BRL', value: Number(value || 0) }); }; } function init() { if ((window.location.pathname.replace(/\/+$/, '') || '/') !== '/checkout') return; addBoletoOption(); preventPrematurePurchaseEvents(); bindPaymentAnalytics(); } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); } else { init(); } })();